import{_ as e,c as t,o as d,b0 as o}from"./chunks/framework.C5ev1SXp.js";const s="/scm-docs/assets/flash-sram-map.CXgpGWK0.svg",u=JSON.parse('{"title":"LV030-FLASH APP设计","description":null,"frontmatter":{"title":"LV030-FLASH APP设计","date":"2026-10-17T19:10:00.000Z","icon":"famicons:logo-markdown","permalink":"/sdoc/online-upgrade/iap/126b0fcbd40c60cd0540e","index":true,"tags":null,"categories":["在线升级"],"copyright":false,"keywords":null,"cover":null,"comments":null,"mathjax":null,"top":null,"description":null,"tdoc":{"detailDate":"2026-10-17T19:10:00.520Z","fulluuid":"60cd0540ecbd40cf930b31e1876d5011","useduuid":"60cd0540e"}},"headers":[],"relativePath":"sdoc/online-upgrade/iap/126b0fcbd40c60cd0540e.md","filePath":"sdoc/70-在线升级/01-IAP/LV030-FLASH-APP设计.md","lastUpdated":1792231946000}'),i={name:"sdoc/online-upgrade/iap/126b0fcbd40c60cd0540e.md"};function l(r,a,c,n,h,p){return d(),t("div",null,[...a[0]||(a[0]=[o('<h1 id="lv030-flash-app设计" tabindex="-1">LV030-FLASH APP设计 <a class="header-anchor" href="#lv030-flash-app设计" aria-label="Permalink to &quot;LV030-FLASH APP设计&quot;">​</a></h1><h2 id="一、-定位与功能" tabindex="-1">一、 定位与功能 <a class="header-anchor" href="#一、-定位与功能" aria-label="Permalink to &quot;一、 定位与功能&quot;">​</a></h2><h3 id="_1-它解决什么问题" tabindex="-1">1. 它解决什么问题 <a class="header-anchor" href="#_1-它解决什么问题" aria-label="Permalink to &quot;1. 它解决什么问题&quot;">​</a></h3><p><code>flash-app</code> 是 IAP 方案里&quot;被升级的那一方&quot;，也是整个方案的主线：它从内部 Flash 第 2 块（<code>0x08020000</code>）运行，因此可以通过网络或串口把新的镜像写进同一块区域来替换自己。所有&quot;下载、校验、落盘&quot;的设计都是为了让这个目标成立。</p><p>它与 Bootloader 的关系是一次性的交接：Bootloader 在 <code>0x08000000</code> 完成初始化、判断 APP 区有没有合法镜像，然后把控制权交出去，此后不再参与运行。</p><h3 id="_2-功能清单" tabindex="-1">2. 功能清单 <a class="header-anchor" href="#_2-功能清单" aria-label="Permalink to &quot;2. 功能清单&quot;">​</a></h3><table tabindex="0"><thead><tr><th>功能</th><th>实现位置</th><th>说明</th></tr></thead><tbody><tr><td>串口日志输出</td><td><code>fputc()</code> 重定向到 USART1</td><td>115200，中断接收、轮询发送</td></tr><tr><td>行命令 <code>reboot</code></td><td><code>app_cmd_reboot()</code></td><td>打印后等 <code>TC</code>，软复位回 Bootloader</td></tr><tr><td>串口回显</td><td><code>usart_echo_test()</code></td><td>把收到的整行原样回发，用于验证链路</td></tr><tr><td>看门狗</td><td><code>iwdg_start()</code> + 主循环喂狗</td><td>3 秒超时，初始化完成后使能</td></tr><tr><td>网络</td><td>无</td><td><code>flash-app</code> 不含 lwIP 与 DM9000 驱动</td></tr></tbody></table><p>一句话概括：它是个最小可运行的应用，只保留&quot;证明自己活着&quot;和&quot;能被重启回升级流程&quot;两件事。业务代码是后续往上加的，升级通道与启动衔接已经打通。</p><h3 id="_3-与其它镜像的关系" tabindex="-1">3. 与其它镜像的关系 <a class="header-anchor" href="#_3-与其它镜像的关系" aria-label="Permalink to &quot;3. 与其它镜像的关系&quot;">​</a></h3><table tabindex="0"><thead><tr><th>镜像</th><th>落盘位置</th><th>运行位置</th><th>交付方式</th></tr></thead><tbody><tr><td>Bootloader</td><td><code>0x08000000</code></td><td><code>0x08000000</code></td><td>SWD 下载</td></tr><tr><td><code>flash-app</code></td><td><code>0x08020000</code></td><td><code>0x08020000</code></td><td><code>app.img</code>，经串口/TCP 写回</td></tr><tr><td><code>sram-app</code></td><td><code>0x08040000</code> 暂存</td><td><code>0x20007000</code></td><td><code>app.img</code>，再 <code>go sram</code> 搬运</td></tr></tbody></table><p><code>sram-app</code> 与 <code>flash-app</code> 源码同源、链接地址不同，功能集合基本一致；差别在于 <code>sram-app</code> 掉电即失、需要额外的装载步骤（见 <code>LV035-SRAM-APP设计</code>）。</p><h2 id="二、-链接地址" tabindex="-1">二、 链接地址 <a class="header-anchor" href="#二、-链接地址" aria-label="Permalink to &quot;二、 链接地址&quot;">​</a></h2><h3 id="_1-irom1-与-iram1-的取值" tabindex="-1">1. IROM1 与 IRAM1 的取值 <a class="header-anchor" href="#_1-irom1-与-iram1-的取值" aria-label="Permalink to &quot;1. IROM1 与 IRAM1 的取值&quot;">​</a></h3><table tabindex="0"><thead><tr><th>项</th><th>取值</th><th>含义</th></tr></thead><tbody><tr><td>IROM1</td><td><code>0x08020000</code>，大小 <code>0x20000</code>（128KB）</td><td>代码与只读数据的起始地址与容量</td></tr><tr><td>IRAM1</td><td><code>0x20000000</code>，大小 <code>0x10000</code>（64KB）</td><td>全局变量、堆、栈；此时 Bootloader 已退出，整块 RAM 可用</td></tr></tbody></table><p><img src="'+s+`" alt="内部 FLASH 与 SRAM 地址分区"></p><h3 id="_2-为什么必须是-0x08020000" tabindex="-1">2. 为什么必须是 0x08020000 <a class="header-anchor" href="#_2-为什么必须是-0x08020000" aria-label="Permalink to &quot;2. 为什么必须是 0x08020000&quot;">​</a></h3><p>三个原因叠加，缺一不可：</p><ul><li>Bootloader 自己占第 1 块（<code>0x08000000</code> ~ <code>0x08020000</code>），APP 必须让开；</li><li>IAP 的帧头只接受两个容器基址，<code>0x08020000</code> 是其中之一（另一个是 <code>0x20007000</code>），别的地址直接拒绝，不做&quot;就近对齐&quot;这种猜测；</li><li>页擦除以 2KB 为粒度，128KB 块边界正好是页边界，擦除时不会碰到 Bootloader。</li></ul><h3 id="_3-向量表与-app-base" tabindex="-1">3. 向量表与 APP_BASE <a class="header-anchor" href="#_3-向量表与-app-base" aria-label="Permalink to &quot;3. 向量表与 APP_BASE&quot;">​</a></h3><p>APP 自己的向量表就放在镜像起始处，<code>main()</code> 开头、<code>HAL_Init()</code> 之前先重定位一次：</p><div class="language-c vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// flash-app/Core/Src/main.c</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">#ifndef</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> APP_BASE</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">#define</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> APP_BASE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  0x</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">08020000</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">U</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     /* IAP_APP_BASE: 与 IROM1 / pack_iap.py 一致 */</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">#endif</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">/* 向量表重定位到 APP 基址: 必须早于 HAL_Init(), 否则中断仍会走 Bootloader 的向量表 */</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">SCB</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">VTOR </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> APP_BASE;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p>这一步在&quot;由 Bootloader 跳转&quot;时是冗余的（跳转前已经设过），但它让镜像具备&quot;独立启动&quot;的能力：只要把 <code>APP_BASE</code> 覆盖成实际链接地址，同一个工程既能被 IAP 装载，也能被调试器直接下载运行。</p><h2 id="三、-工程与构建" tabindex="-1">三、 工程与构建 <a class="header-anchor" href="#三、-工程与构建" aria-label="Permalink to &quot;三、 工程与构建&quot;">​</a></h2><h3 id="_1-两个-target" tabindex="-1">1. 两个 Target <a class="header-anchor" href="#_1-两个-target" aria-label="Permalink to &quot;1. 两个 Target&quot;">​</a></h3><p><code>flash-app.uvprojx</code> 里有两个 Target，源码完全共享，只有宏定义不同：</p><table tabindex="0"><thead><tr><th>Target</th><th>宏</th><th>链接地址</th><th>用途</th></tr></thead><tbody><tr><td><code>flash-app</code></td><td>默认，<code>APP_BASE=0x08020000</code></td><td><code>0x08020000</code></td><td>交付镜像，走 <code>app.img</code></td></tr><tr><td><code>flash-app-debug</code></td><td><code>FLASH_APP_BASE=0x08000000</code></td><td><code>0x08000000</code></td><td>直跑调试，SWD 下载后直接启动</td></tr></tbody></table><p><code>flash-app-debug</code> 的存在解决了一个具体问题：IAP 链路没跑通时，仍然需要一个&quot;能独立上电运行&quot;的版本去验证业务代码。它覆盖掉 Bootloader 的地址，因此<strong>只能配合整片擦除的下载方式</strong>——用调试器下载它会把 Bootloader 覆盖掉。</p><p>构建脚本也据此加了门禁：<code>-d</code> 只对 <code>-t debug</code> 生效，release 目标带 <code>-d</code> 只提示不下载（见 <code>build_flash.ps1</code>）。</p><h3 id="_2-构建产物" tabindex="-1">2. 构建产物 <a class="header-anchor" href="#_2-构建产物" aria-label="Permalink to &quot;2. 构建产物&quot;">​</a></h3><p>一次 release 构建会产出三个文件，各有明确用途：</p><table tabindex="0"><thead><tr><th>产物</th><th>生成方式</th><th>用途</th></tr></thead><tbody><tr><td><code>flash-app.axf</code></td><td>ARMCC 链接输出</td><td>调试符号，J-Link 下载用</td></tr><tr><td><code>flash-app.bin</code></td><td><code>fromelf --bin</code></td><td>裸镜像，给 <code>pack_iap.py</code> 打包</td></tr><tr><td><code>app.img</code></td><td>构建后自动执行 <code>tools/pack_iap.py</code></td><td>IAP 的传输格式</td></tr></tbody></table><p><code>.bin</code> 与 <code>app.img</code> 的关系见 <code>LV040-image镜像文件打包原理与生成</code>。</p><h3 id="_3-构建命令" tabindex="-1">3. 构建命令 <a class="header-anchor" href="#_3-构建命令" aria-label="Permalink to &quot;3. 构建命令&quot;">​</a></h3><div class="language-powershell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># release: 生成 app.img，供串口/TCP 下载</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.\\build_flash.ps1 </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">b</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 调试: 链接到 0x08000000，可 SWD 直接下载</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.\\build_flash.ps1 </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">b </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">t debug </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><h2 id="四、-上电到运行" tabindex="-1">四、 上电到运行 <a class="header-anchor" href="#四、-上电到运行" aria-label="Permalink to &quot;四、 上电到运行&quot;">​</a></h2><h3 id="_1-bootloader-的判定" tabindex="-1">1. Bootloader 的判定 <a class="header-anchor" href="#_1-bootloader-的判定" aria-label="Permalink to &quot;1. Bootloader 的判定&quot;">​</a></h3><p>Bootloader 启动后不会无条件跳转，先看 <code>0x08020000</code> 处的向量表：</p><ul><li>初始栈顶必须落在 <code>0x20000000</code> ~ <code>0x20010000</code>；</li><li>复位向量必须落在 <code>0x08020000</code> ~ <code>0x08040000</code> 内，且最低位为 1（Thumb 地址）。</li></ul><p>两条都过才跳，否则停在命令行等待下载。所以&quot;APP 区是空的&quot;不会导致跑飞，只会看到 Bootloader 的命令提示。</p><h3 id="_2-运行时的内存分配" tabindex="-1">2. 运行时的内存分配 <a class="header-anchor" href="#_2-运行时的内存分配" aria-label="Permalink to &quot;2. 运行时的内存分配&quot;">​</a></h3><p><code>flash-app</code> 运行期间独占内部 SRAM：<code>.data</code> 由 <code>__main</code> 从 Flash 拷贝到 RAM，<code>.bss</code> 清零，栈顶由向量表第 1 项给出（初始值 <code>0x20010000</code>）。Bootloader 此时已经交出控制权，它的 RW/ZI 不再被访问，因此不存在抢占 RAM 的问题。</p><h3 id="_3-交给它的硬约束" tabindex="-1">3. 交给它的硬约束 <a class="header-anchor" href="#_3-交给它的硬约束" aria-label="Permalink to &quot;3. 交给它的硬约束&quot;">​</a></h3><ul><li>链接地址一旦改动，<code>pack_iap.py</code> 的 <code>APP_BASE</code>、<code>iap.h</code> 的 <code>IAP_APP_BASE</code>、向量表合法性检查三处都要同步；</li><li>镜像不能超过 128KB，<code>pack_iap.py</code> 在打包阶段就会拒绝超限；</li><li>中断向量表必须随镜像一起落盘（它在镜像头部），否则跳转后第一次中断就会取到 Bootloader 的处理函数。</li></ul><h2 id="五、-常见问题" tabindex="-1">五、 常见问题 <a class="header-anchor" href="#五、-常见问题" aria-label="Permalink to &quot;五、 常见问题&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>原因</th><th>处理</th></tr></thead><tbody><tr><td>下载后敲 <code>go flash</code> 没反应，日志说 <code>no app</code></td><td>APP 区未写入或向量表不合法</td><td>先发 <code>flash-app</code> 的 <code>app.img</code>，确认 <code>flash write OK</code></td></tr><tr><td>跳转后立刻 HardFault</td><td>镜像链接地址与帧头地址不一致</td><td>用 <code>-t debug</code> 编出的镜像走 IAP 就会这样，改用 release 构建</td></tr><tr><td>串口无输出</td><td><code>flash-app-debug</code> 覆盖了 Bootloader，但没整片擦除</td><td>重新整片擦除后再下载，或先下载 Bootloader</td></tr><tr><td>复位后回到 Bootloader 而不是 APP</td><td>正常运行行为</td><td>Bootloader 每次上电都要重新判定，用 <code>go flash</code> 或等自动跳转</td></tr></tbody></table><hr><p><em>本文档由 markdowncli 技能辅助生成</em></p>`,47)])])}const k=e(i,[["render",l]]);export{u as __pageData,k as default};
